import * as CookieConsent from "vanilla-cookieconsent"
import type { CookieConsentConfig } from "vanilla-cookieconsent"
import { createConfig, type CreateConfigOptions } from "./config"

export { createConfig }
export type { CreateConfigOptions, ConsentCategory, ConsentCopy } from "./config"
export type { CookieConsentConfig }

let initialized = false

export type InitOptions = CreateConfigOptions & {
    /**
     * Provide a fully-formed vanilla-cookieconsent config instead of building one
     * from the high-level options. When set, all other options are ignored.
     */
    config?: CookieConsentConfig
}

/**
 * Initialise the consent manager. Safe to call more than once (e.g. React
 * StrictMode double-invoke) — only the first call runs.
 *
 * Scripts are gated declaratively:
 *   <script type="text/plain" data-category="analytics">…</script>
 */
export function init(options: InitOptions = {}): void {
    if (initialized || typeof document === "undefined") return
    initialized = true
    const { config, ...configOptions } = options
    void CookieConsent.run(config ?? createConfig(configOptions))
}

/** Re-open the preferences modal (e.g. from a "Manage cookies" link). */
export function showPreferences(): void {
    CookieConsent.showPreferences()
}

/** Show the main consent modal. */
export function show(createModal?: boolean): void {
    CookieConsent.show(createModal)
}

/** Whether the given category is currently accepted. */
export function acceptedCategory(category: string): boolean {
    return CookieConsent.acceptedCategory(category)
}

/** Whether a valid consent choice has already been recorded. */
export function validConsent(): boolean {
    return CookieConsent.validConsent()
}

/** Programmatically accept categories: "all", "necessary", or a specific list. */
export function acceptCategory(
    categories?: string[] | "all" | "necessary",
    excluded?: string[],
): void {
    CookieConsent.acceptCategory(categories as never, excluded)
}

/** Escape hatch: the underlying vanilla-cookieconsent module. */
export { CookieConsent }
